#!/usr/bin/env node
/**
 * Wave F6 — Module Build Playbook code-reference refresher.
 *
 * Scans the analytics module (the canonical reference per the F-plan)
 * and emits an up-to-date manifest of file paths + line anchors that
 * the living playbook should cite. The playbook itself
 * (docs/module-build-playbook-d45c82.md) embeds these refs through
 * the marker block:
 *
 *   <!-- PLAYBOOK_REFS:BEGIN -->
 *   ...auto-generated table...
 *   <!-- PLAYBOOK_REFS:END -->
 *
 * Re-running this script regenerates the table in place. The CI guard
 * `scripts/ci-guards/playbook-code-references-fresh.mjs` then asserts
 * that the on-disk file matches the regeneration result (no drift).
 */

import { existsSync, readFileSync, writeFileSync, statSync } from 'node:fs';
import { resolve, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');

const CANONICAL_REFS = [
  ['module.manifest', 'modules/analytics/module.manifest.json'],
  ['routing',         'platform/foundation/contracts/routing/routes.json'],
  ['permissions',     'platform/foundation/contracts/permissions/permissions.json'],
  ['role-profile',    'platform/foundation/contracts/role-profile-sync.contract.json'],
  ['db.tenant.001',   'platform/foundation/db/tenant/migrations/001_foundation_tenant_tables.sql'],
  ['db.tenant.002',   'platform/foundation/db/tenant/migrations/002_foundation_tenant_extended.sql'],
  ['handover.f0',     'scripts/handover/foundation-activation-check.mjs'],
  ['handover.f3',     'scripts/handover/foundation-rbac-matrix.mjs'],
  ['handover.f4',     'scripts/handover/foundation-handover.mjs'],
  ['audit-shelf',     'modules/audit-shelf/module.manifest.json'],
  ['audit-shelf.bundle', 'modules/audit-shelf/scripts/audit-shelf-bundle.mjs'],
];

const PLAYBOOK_PATH = join(ROOT, 'docs', 'module-build-playbook-d45c82.md');
const BEGIN = '<!-- PLAYBOOK_REFS:BEGIN -->';
const END   = '<!-- PLAYBOOK_REFS:END -->';

function refRow([key, rel]) {
  const abs = join(ROOT, rel);
  if (!existsSync(abs)) return `| \`${key}\` | \`${rel}\` | _missing_ | — |`;
  const st = statSync(abs);
  const content = readFileSync(abs, 'utf8');
  const lines = content.split('\n').length;
  const sizeKB = (st.size / 1024).toFixed(1);
  return `| \`${key}\` | \`${rel}\` | ${lines} lines | ${sizeKB} KB |`;
}

const refsTable = [
  '| key | path | lines | size |',
  '|-----|------|-------|------|',
  ...CANONICAL_REFS.map(refRow),
].join('\n');

const refsBlock = `${BEGIN}\n<!-- auto-generated by scripts/playbook/refresh-code-refs.mjs -->\n${refsTable}\n${END}`;

let body;
if (!existsSync(PLAYBOOK_PATH)) {
  body = [
    '# Module Build Playbook',
    '',
    '_Living document — code references are auto-refreshed by_ `scripts/playbook/refresh-code-refs.mjs`.',
    '',
    '## Canonical Code References',
    '',
    refsBlock,
    '',
    '## Build Order',
    '',
    '1. Authoring contracts (manifest, routing, permissions).',
    '2. DB tenant tables (canonical + extended).',
    '3. Role-profile-as-sole-sync substrate (Wave F1).',
    '4. Test-user fixtures (Wave F2).',
    '5. Activation check 8-cell matrix (Wave F0).',
    '6. RBAC matrix 64-cell (Wave F3).',
    '7. Handover orchestrator (Wave F4).',
    '8. Audit-shelf bundle (Wave F5).',
    ''
  ].join('\n');
} else {
  body = readFileSync(PLAYBOOK_PATH, 'utf8');
  if (body.includes(BEGIN) && body.includes(END)) {
    const before = body.slice(0, body.indexOf(BEGIN));
    const after  = body.slice(body.indexOf(END) + END.length);
    body = before + refsBlock + after;
  } else {
    body = body.trimEnd() + '\n\n## Canonical Code References\n\n' + refsBlock + '\n';
  }
}

writeFileSync(PLAYBOOK_PATH, body);
console.log(`[playbook] refreshed ${CANONICAL_REFS.length} references → ${PLAYBOOK_PATH.replace(ROOT+'/','')}`);
